#
# impact.map -- declarative source-to-target map for prober/verify-impact.
#
# WHY. Every *_test.c links the whole prober LIB (see build.sh:58), so a
# compiler .d file alone would tell you a change to json.c reaches every unit
# binary -- true but useless for selecting the ONE test that actually proves
# the change. This file records the PRIMARY semantic owner explicitly (a
# json.c change is proven first and foremost by json_test) while the LIB-wide
# fallback still applies for anything not listed here (see FALLBACK row).
#
# SCHEMA. TSV, one row per edge, fields separated by a single tab:
#
#   TYPE<TAB>SOURCE<TAB>TARGET<TAB>LANE
#
#   TYPE    one of: PRIMARY, SEMANTIC, FALLBACK, SLOW
#   SOURCE  a path or glob relative to the repo root (prober/json.c,
#           prober/scenarios/backend-smoke/**, prober/fuzz/fuzz_json.c).
#           A bare glob with no directory is matched against the basename.
#   TARGET  the artifact that exercises SOURCE: a unit binary name
#           (json_test), a fuzz target (fuzz/fuzz_json), a scenario dir
#           (scenarios/backend-smoke), a mutation name substring (as passed to
#           mutate.sh's positional filter), or "ALL_UNIT_TESTS" for the LIB
#           fallback.
#   LANE    fast (runs on every PR) or slow (valgrind/weekly/soak -- owner
#           only, verify-impact reports it but does not gate PR CI on it).
#
# Comment lines (#) and blank lines are ignored. Rows are free-form order in
# this file; verify-impact sorts its OWN output, not this map.
#
# GENERATED EDGES. Header (.h) and #include edges are NOT hand-listed here --
# they come from compiler .d files, either emitted by build.sh when
# PROBER_EMIT_DEPS=1 (writes prober/*.d next to each object) or synthesized
# on demand by `verify-impact --regen-deps` (runs $CC -MM per source). Rows
# below marked SEMANTIC are edges no #include expresses (a scenario conf that
# exercises rules.c's reload path, a fuzz target keyed to one parser) and are
# the only hand-written class that is safe to keep by hand: it does not drift
# out of sync with the source the way a header list would.

# --- PRIMARY: one owning unit test per LIB translation unit (build.sh:58) ---
PRIMARY	prober/json.c	json_test	fast
PRIMARY	prober/rules.c	rules_test	fast
PRIMARY	prober/http.c	http_test	fast
PRIMARY	prober/backend.c	backend_test	fast
PRIMARY	prober/util.c	util_test	fast
PRIMARY	prober/assert.c	assert_test	fast

# lib.sh is bash, not a LIB translation unit, but it owns the arithmetic the
# resource oracles assert through and slope_check_test.sh pins that arithmetic
# with no server involved -- so a change to it gets a FAST answer on the PR
# lane here, not only the weekly SLOW scenario rows further down. Those rows
# stay: they cover the live boot/probe path this test deliberately stubs out.
PRIMARY	prober/lib.sh	slope_check_test.sh	fast

# Same reasoning for the two other lib.sh gates that need no server: the stale
# artifact check and the pre-boot conf gate. Both are pure shell over staged
# fixtures, so they answer on the PR lane in milliseconds. check_conf_test.sh
# had no row at all until s143 -- the same unmapped-suite gap that let the
# slope-floor bug (#134) live in a function with zero fast-lane coverage.
PRIMARY	prober/lib.sh	stale_so_test.sh	fast
PRIMARY	prober/lib.sh	check_conf_test.sh	fast

# The suite is its own owner: editing a test must select that test, or the
# selector fails closed on an unmapped executable change (which is exactly what
# it did on the PR that added this file).
PRIMARY	prober/slope_check_test.sh	slope_check_test.sh	fast
PRIMARY	prober/stale_so_test.sh	stale_so_test.sh	fast
PRIMARY	prober/check_conf_test.sh	check_conf_test.sh	fast
PRIMARY	prober/docs_directives_test.sh	docs_directives_test.sh	fast

# test.sh is the RUNNER, not a suite: it discovers *_test.c and *_test.sh and
# aggregates their exit codes. runner_summary_test.sh drives a COPY of it in a
# fixture directory, so it is the suite that actually proves the runner's
# discovery, aggregation and summary reporting.
PRIMARY	prober/test.sh	runner_summary_test.sh	fast
PRIMARY	prober/runner_summary_test.sh	runner_summary_test.sh	fast

# --- FALLBACK: any LIB .c not caught above (or any LIB .c at all, as the
# conservative catch-all every *_test.c binary links against) still selects
# every unit test, because every *_test.c binary links the whole LIB and a
# defect can surface through any of them regardless of which owns the change
# semantically. This is intentionally coarse -- it is a safety net, not the
# primary selection signal.
FALLBACK	prober/json.c	ALL_UNIT_TESTS	fast
FALLBACK	prober/rules.c	ALL_UNIT_TESTS	fast
FALLBACK	prober/http.c	ALL_UNIT_TESTS	fast
FALLBACK	prober/backend.c	ALL_UNIT_TESTS	fast
FALLBACK	prober/util.c	ALL_UNIT_TESTS	fast
FALLBACK	prober/assert.c	ALL_UNIT_TESTS	fast

# --- SEMANTIC: fuzz targets keyed to the parser they drive (fuzz/fuzz.sh) ---
SEMANTIC	prober/json.c	fuzz/fuzz_json	fast
SEMANTIC	prober/http.c	fuzz/fuzz_http	fast
SEMANTIC	prober/fuzz/fuzz_json.c	fuzz/fuzz_json	fast
SEMANTIC	prober/fuzz/fuzz_http.c	fuzz/fuzz_http	fast
SEMANTIC	prober/fuzz/fuzz_memcached.c	fuzz/fuzz_memcached	fast
SEMANTIC	prober/fuzz/fuzz_resp.c	fuzz/fuzz_resp	fast
SEMANTIC	prober/fuzz/corpus	fuzz/fuzz_json	fast

# --- SEMANTIC: mutation owners (mutate.sh NAME<->file pairing, see mutate.sh)
SEMANTIC	prober/http.c	mutate:send_slow	fast
SEMANTIC	prober/http.c	mutate:abort	fast
SEMANTIC	prober/http.c	mutate:recv_slow	fast
SEMANTIC	prober/http.c	mutate:shutdown	fast
SEMANTIC	prober/http.c	mutate:so_rcvbuf	fast
SEMANTIC	prober/http.c	mutate:hold	fast
SEMANTIC	prober/rules.c	mutate:shutdown	fast
SEMANTIC	prober/rules.c	mutate:abort	fast
SEMANTIC	prober/rules.c	mutate:send_slow	fast

# --- SEMANTIC: scenario tree exercises the live probe compiled against a
# real nginx/angie -- no #include links prober/scenarios/** back to src/, the
# link is "this scenario's driver.sh boots a probe built from this source".
SEMANTIC	prober/scenarios	scenarios/*	fast
SEMANTIC	src/ngx_test_probe_arm.c	scenarios/*	fast
SEMANTIC	src/ngx_test_probe_arm.c	t/*	fast

# The probe renderer (src/ngx_test_probe.c) emits the document schema_test.c and
# schema_emitter_test.sh pin the SHAPE of, and every scenario boots a server
# built from it. probe-schema.json is the checked-in shape contract those tests
# read. A change to either selects the two schema gates (which run in the
# selftest job, no server) plus the scenario tree (which boots the live probe).
SEMANTIC	src/ngx_test_probe.c	schema_test	fast
SEMANTIC	src/ngx_test_probe.c	scenarios/*	fast
SEMANTIC	probe-schema.json	schema_test	fast

# --- SEMANTIC: the selector's own inputs. impact.map and verify-impact are
# proven by their own self-test, not by any unit/fuzz/scenario target above.
SEMANTIC	prober/impact.map	verify_impact_test.sh	fast
SEMANTIC	prober/verify-impact	verify_impact_test.sh	fast
SEMANTIC	prober/pr-memcheck	pr_memcheck_test	fast

# --- SLOW: owners that only run out-of-band (Valgrind/weekly/soak), not on
# every PR. verify-impact reports these under the "slow" lane so --explain
# can show them, but PR CI (P2-A's own scope) does not gate on the slow lane.
SLOW	prober/backend.c	scenarios/reload-soak	slow
SLOW	prober/http.c	scenarios/soak-delta	slow
SLOW	prober/rules.c	scenarios/property-fuzz	slow
# The resource-scoreboard slope oracle (P2-E) is a soak: it runs N post-warmup
# operations to measure a per-op slope, so it belongs in the weekly/slow lane
# like the other soaks, not the PR path ("PR runs the mapped smallest case;
# slope/soak is weekly" -- plan.md P2-E).
SLOW	prober/lib.sh	scenarios/rss-slope	slow
SLOW	src/ngx_test_probe.c	scenarios/rss-slope	slow
# The stateful property-fuzz model (P2-G5) drives a generated SEQUENCE of
# connection-lifecycle + signal (reload/kill) steps and checkpoints worker
# lineage/log/pool/generation/zone after each. It boots a real server, fires
# signals and drains between steps, so it is a soak on the weekly lane like
# property-fuzz -- not the PR path ("PR runs only models mapped from the diff
# and stays inside P2-C; discovery is weekly" -- plan.md P2-G5). Its lib.sh
# owner is the signal/drain/config-wait helper set it choreographs.
SLOW	prober/rules.c	scenarios/stateful-property-fuzz	slow
SLOW	prober/lib.sh	scenarios/stateful-property-fuzz	slow
SLOW	src/ngx_test_probe.c	scenarios/stateful-property-fuzz	slow
# The named fault matrix (P2-G6) sweeps every fakesrv upstream fault (reset,
# short read, length under/overcount, drip, idle close) through nginx's memcached
# upstream and, after each, reads fd + cycle-pool neutrality from the probe. It
# boots a real server and issues an ordinal-keyed sequence of faulted upstream
# requests, so it is a weekly-lane sweep like property-fuzz -- not the PR path
# ("PR injects only sites in the impact set; weekly sweeps the matrix" -- plan.md
# P2-G6). Its owners are the fake backend's fault model and the probe's resource
# fields the oracle reads.
SLOW	prober/backend.c	scenarios/fault-matrix	slow
SLOW	src/ngx_test_probe.c	scenarios/fault-matrix	slow
# The deployment canary / shadow verifier (P2-H) sequential-boots a CONTROL
# then a CANDIDATE server from the same conf, drives a fixed GET/HEAD request
# plan at each, diffs status/headers/body, and slope-checks the candidate's
# own cycle_used/private_dirty across a post-warmup sweep. Two boots plus a
# slope is a soak like rss-slope -- weekly lane, not the PR path (design pass:
# memory/labs/nginx-test-harness/design-p2h-canary.md D-8). Its owners are the
# boot/probe/slope helper set (lib.sh) and the probe document the differential
# and O7 growth oracles both read.
SLOW	prober/lib.sh	scenarios/deploy-canary	slow
SLOW	src/ngx_test_probe.c	scenarios/deploy-canary	slow
